class Pluck {
	// Base drawing scales. Note: p5.js has 'width' and 'height' globally available after setup().

	constructor(i_c, i_weight) {
		this.ascale = 300;
		this.fscale = 0.5 * TWO_PI; // width will be divided dynamically later
		this.c = i_c;
		this.weight = i_weight;
		this.a = 0; // amplitude (starts as 1 +/-)
		this.d = 0; // decay rate
		this.f = 0; //frequemcy
		this.o = 0; // start offset
		this.a_start = 0;
		this.active = false;
		this.on = false;
		this.wave = new p5.Oscillator();
	}

	trigger(i_a, i_d, i_f, i_o) { // trigger the pluck
		this.a = i_a;
		this.d = i_d;
		this.f = i_f;
		this.o = i_o;

		//	console.log(this.f);

		this.a_start = this.a;
		this.active = true;
		this.on = true;

		this.wave.setType('sine');
		this.wave.freq(this.f);

		this.wave.amp(0);
		this.wave.start();
	}

	display() {

		if (this.on) {
			noiseDetail(10, 0.66);
			push();

			// Ensure fscale is updated if width changes dynamically
			this.fscale = 0.005 * TWO_PI / width;

			let y_val = []; // main stroke
			let dust = [];

			// calculate the sin wave; 
			for (let i = 0; i < width; i++) {
				y_val[i] = this.a * this.ascale * sin(this.f * this.fscale * i - (counter + this.o) / 8.0);

				// Using noise with a slightly different scaling for the second argument to randomly create dust particles
				if (pow(min(1, noise(i * 0.1 - counter / 5.0, y_val[i] * 0.00001 - i * 0.1)), 2) > 0.999) {
					dust.push(i);
				}
			}

			this.wave.pan(0.6 * sin((counter + this.o) / 8.0)); // pan based on phase offset

			strokeJoin(ROUND);
			strokeCap(ROUND);

			// main line
			strokeWeight(this.weight);
			// Processing's color() with a single argument for the existing color object is unique.
			// In p5.js, we extract components and create a new color with modified alpha.
			stroke(color(red(this.c), green(this.c), blue(this.c), (alpha(this.c) * this.a / this.a_start + 16)));
			beginShape();
			for (let i = 0; i < width; i++) {
				vertex(i, y_val[i]);
			}
			endShape();

			// blur line
			strokeWeight(this.weight * 5.0);
			stroke(color(red(this.c), green(this.c), blue(this.c), (alpha(this.c) * this.a / this.a_start + 16) / 2.0));
			beginShape();
			for (let i = 0; i < width; i++) {
				vertex(i, y_val[i]);
			}
			endShape();

			// big blur line
			strokeWeight(this.weight * 13.0);
			stroke(color(red(this.c), green(this.c), blue(this.c), (alpha(this.c) * this.a / this.a_start + 16) / 4.0));
			beginShape();
			for (let i = 0; i < width; i++) {
				vertex(i, y_val[i]);
			}
			endShape();

			// dust motes
			// lerpColor in p5.js takes two color objects and an amount (0-1)
			stroke(lerpColor(color(red(this.c), green(this.c), blue(this.c), alpha(this.c) * this.a / this.a_start), color(255, 255, 255, -200 + alpha(this.c) * this.a / this.a_start), 0.7));
			for (let i = 0; i < dust.length; i++) {
				strokeWeight(this.weight);
				point(dust[i], y_val[dust[i]]);
				strokeWeight(this.weight * 3.0);
				point(dust[i], y_val[dust[i]]);
				strokeWeight(this.weight * 7.0);
				point(dust[i], y_val[dust[i]]);
				strokeWeight(this.weight * 13.0);
				point(dust[i], y_val[dust[i]]);
				push();
				strokeWeight(4);
				line(dust[i], y_val[dust[i]] - this.weight * 12.0, dust[i], y_val[dust[i]] + this.weight * 12.0);
				pop();
			}



			if (this.active) {
				this.a *= (1 - this.d); // decay
				this.wave.amp(map(this.a, 0, 1.5, 0, 0.3));
			}
			if (this.a < 0.001) {
				this.active = false; // faded out
				this.wave.stop();
				this.wave.amp(0);
			}
			pop();
		}
	}
}

