let counter;
let mypluck = [];

const numNotes = 8;  //higher than 10 gets slow for me...
const loF = 150; //Hz
const hiF = 2000; //Hz

let colors = [
  '#FF6464FF', '#64FF64FF', '#6464FFFF',
  '#FFFF64FF', '#FF64FFFF', '#64FFFFFF'
];

function mousePressed() {
  // In p5.js, mouseButton is a global variable (LEFT, RIGHT, CENTER)
  if (mouseButton === LEFT) {
    setup(); 
	} else if (mouseButton === RIGHT) {
    capture();
  }
}

function capture() {
  // p5.js provides year(), month(), day(), hour(), minute(), second()
  // Use template literals for string formatting instead of nf()
  let fname = `Image_${year()}${nf(month(), 2)}${nf(day(), 2)}${nf(hour(), 2)}${nf(minute(), 2)}${nf(second(), 2)}`;
 console.log(`Saved ${fname}.png`); // println becomes console.log
  save(fname + ".png");
}

function setup() {
  // createCanvas is the p5.js equivalent of size()
  createCanvas(1080,1080, P2D); 
  smooth(); 
  noFill(); // Call noFill once in setup

  background(0);
  counter = 0;

	for (let i=0; i<mypluck.length; i++) { //stop any existing oscillators in case of rerun
		mypluck[i].wave.stop();
	}

  mypluck = []; // Re-initialize the array for a clean start

  for (let i = 0; i < numNotes; i++) { 
    mypluck[i] = new Pluck(color(random(colors)), 1.5);
    mypluck[i].trigger(1.0 + randomGaussian() / 2, random(0.01, 0.05), getGaussianRandom(loF,hiF), i);
    mypluck[i].on = false;
  }
}

function initSketch() {

}

function draw() {
  background(0);

  // Translate is global to the canvas transform matrix
  translate(0, height / 2); // 0 in center

  //console.log(counter);

  if (counter < mypluck.length * 60) {
    if (counter % 60 === 0) {
      // Accessing array elements mypluck[floor(counter / 60)]
      mypluck[floor(counter / 60)].trigger(min(1.0 + randomGaussian() / 2, 1.5), 0.01, getGaussianRandom(loF,hiF), floor(counter / 60));
    }
  }

  for (let i = 0; i < mypluck.length; i++) {
    if (!mypluck[i].active) {
      mypluck[i] = new Pluck(color(colors[floor(random(0, colors.length))]), 1.5);
      mypluck[i].trigger(min(1.0 + randomGaussian() / 2, 1.5), random(0.01, 0.05), getGaussianRandom(loF,hiF), i);
    }
    mypluck[i].display();
  }

  counter += 1;
}

function getGaussianRandom(min, max) {
    let u = 0, v = 0;
    // Ensure u and v are not 0 to avoid Math.log(0) which is -Infinity
    while (u === 0) u = Math.random();
    while (v === 0) v = Math.random();

    // Box-Muller transform to get a standard normal deviate (mean 0, std dev 1)
    let z = Math.sqrt(-2.0 * Math.log(u)) * Math.cos(2.0 * Math.PI * v);

    // --- Adjusting for the desired range ---
    // Default mean to the center of the range
    const mean = (min + max) / 2;

    // Default standard deviation such that +/- 2 standard deviations covers
    // approximately 95% of the range. So, 4 * stdDev = (max - min) => stdDev = (max - min) / 4.
    // You can adjust '4' to a smaller number (e.g., 3 for ~99.7% within +/-3 stdDev)
    // to make the curve "wider" within the range, or a larger number to make it "narrower".
    const standardDeviation = (max - min) / 4;

    // Scale and shift the standard normal deviate to your desired mean and stdDev
    let result = z * standardDeviation + mean;

    // --- Truncation / Re-sampling ---
    // If the number falls outside the [min, max] range, re-generate it.
    // This ensures all numbers are within the specified bounds while preserving
    // the Gaussian shape *within* those bounds.
    if (result < min || result > max) {
        return getGaussianRandom(min, max); // Recursive call until it's in range
    }

    return result;
}



